#!/usr/bin/env bash
# Regenerate rust/crates/cairn-build/src/scip/proto.rs from upstream
# sourcegraph/scip's scip.proto via prost-build. This is a DEV-ONLY step --
# the generated file is checked in and the crate ships only the `prost`
# runtime (spec rust-migration D-008), mirroring the Python side's checked-in
# _scip_pb2.py stub.
#
# Usage:
#   scripts/regen_scip_proto.sh [commit-sha] [protoc-binary]
#
# Arguments:
#   commit-sha      scip.proto pin; default resolves the latest commit that
#                   touched scip.proto upstream.
#   protoc-binary   path to a protoc executable; default looks for protoc on
#                   PATH. prost-build 0.14 requires protoc; nothing is
#                   installed by this script.
#
# After regenerating:
#   1. Update the pinned SHA in the provenance header of proto.rs (printed
#      below) and in this script's default if re-pinning.
#   2. Verify parity: cargo test -p cairn-build --test scip_import (the
#      checked-in fixture is produced by the Python reference runtime, so the
#      test failing means field/tag drift).
#   3. Commit proto.rs together with any prost pin change in
#      rust/crates/cairn-build/Cargo.toml -- never let them drift.
set -euo pipefail

COMMIT_ARG="${1:-}"
PROTOC_BIN="${2:-protoc}"
REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="$REPO_ROOT/rust/crates/cairn-build/src/scip/proto.rs"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

if [ -n "$COMMIT_ARG" ]; then
    COMMIT="$COMMIT_ARG"
else
    COMMIT="$(curl -fsSL "https://api.github.com/repos/sourcegraph/scip/commits?path=scip.proto&per_page=1" \
        | python3 -c 'import sys,json;print(json.load(sys.stdin)[0]["sha"])')"
fi
echo "→ fetching scip.proto @ $COMMIT"
curl -fsSL "https://raw.githubusercontent.com/sourcegraph/scip/${COMMIT}/scip.proto" -o "$WORK/scip.proto"

echo "→ generating scip.rs with prost-build (needs cargo + ${PROTOC_BIN})"
mkdir -p "$WORK/codegen/src"
cat > "$WORK/codegen/Cargo.toml" <<'EOF'
[package]
name = "scip-codegen"
version = "0.0.0"
edition = "2021"

[build-dependencies]
prost-build = "=0.14.4"
EOF
cp "$WORK/scip.proto" "$WORK/codegen/scip.proto"
cat > "$WORK/codegen/build.rs" <<'EOF'
fn main() -> Result<(), Box<dyn std::error::Error>> {
    prost_build::Config::new().compile_protos(&["scip.proto"], &["."])?;
    Ok(())
}
EOF
echo 'fn main() {}' > "$WORK/codegen/src/main.rs"
(cd "$WORK/codegen" && PROTOC="$PROTOC_BIN" cargo build 2>/dev/null)
GEN="$(ls "$WORK/codegen/target/debug/build"/scip-codegen-*/out/scip.rs)"

echo "→ installing to $OUT"
cat > "$OUT" <<HEADER
//! Generated by prost-build 0.14.4 from sourcegraph/scip's scip.proto
//! @ ${COMMIT}; DO NOT EDIT.
//! Regenerate via scripts/regen_scip_proto.sh (dev-only; the crate ships the
//! prost runtime only, mirroring the checked-in-stub arrangement of the
//! Python implementation).
HEADER
# scip.proto's examples are EBNF/diagram pseudo-code; bare fences would be
# compiled as Rust doctests, so annotate them text (annotated fences untouched).
sed -E 's|^([[:space:]]*/// ```)$|\1text|' "$GEN" >> "$OUT"

echo
echo "✓ done. Now:"
echo "  - verify parity: cargo test -p cairn-build --test scip_import"
echo "  - update the SHA in this script's docs if it changed"
echo "  - commit proto.rs + Cargo.toml together"
